    "originalJa": "他の人より優れてるものを見つけ出して自慢するっていうか、自分のキャリアだったり、容姿だったり、出身校だったり、趣味とか特技とか。",
    "originalKana": "たのひとよりすぐれてるものをみつけだしてじまんするっていうか、じぶんのキャリアだったり、ようしだったり、しゅっしんこうだったり、しゅみとかとくぎとか。",
